/* Bounded FIFO sibling-subtree windows. Workers never offer work.
 *
 * slots[] always points at the 32 stable controls in tasks[]. Only count
 * controls have byte buffers. first/last/next form the pending FIFO, including
 * RUNNING, DONE/unread, and the head currently being delivered. Claim scans
 * this FIFO for its earliest QUEUED task; release requires DONE and !ready.
 *
 * mutex protects every shared predicate and READY publication/ACK. With
 * ready==0 the producer alone owns bytes/used/channel/flush, and fills outside
 * mutex. Publishing lends those fields to the consumer until ACK. FILE I/O
 * and diagnostics run unlocked while the producer is parked. DONE can coexist
 * with a final READY batch: its producer has exited, without waiting for ACK.
 * Seeds belong to the coordinator; a task borrows immutable parent rules only
 * until drain or abort+join. Each callback releases its actor arena before DONE.
 *
 * N pending tasks and N B-byte mailboxes are bounded, not N listing widths:
 * active listings can reach max(128, 1+127N), plus seeds/ignore/scratch/stacks.
 */
#ifndef FYND_TASK_BYTES
#define FYND_TASK_BYTES 1048576U
#endif
#ifndef FYND_TASK_BEGIN
#define FYND_TASK_BEGIN(task) ((void)0)
#endif
#ifndef FYND_TASK_PUBLISH
#define FYND_TASK_PUBLISH(task) ((void)0)
#endif
#ifndef FYND_PENDING
#define FYND_PENDING(pool) ((void)0)
#endif
#ifndef FYND_POOL_PREPARE
#define FYND_POOL_PREPARE(pool) ((void)0)
#endif

enum { TASK_FREE, TASK_QUEUED, TASK_RUNNING, TASK_DONE };

struct Task {
    Pool *pool;
    CuArena seed;
    const char *path;
    int depth;
    const IgnoreFrame *parent;
    Task *next;
    char *bytes;
    size_t used;
    int channel;
    int flush;
    int write_stopped; /* producer-private; never touch a canceled READY batch */
    int ready;
    int state;
    int status;
    int terminal;
};

typedef struct SubtreeWorker {
    Pool *pool;
    CuThread *thread;
} SubtreeWorker;

struct Pool {
    CuArena arena;
    const Query *query;
    CuMutex *mutex;
    CuCond *work;
    CuCond *publication;
    CuCond *space;
    Task tasks[32];
    Task *slots[32];
    SubtreeWorker workers[32];
    Task *first;
    Task *last;
    int count;
    int pending;
    int started;
    int joined;
    int ready;
    int stop;
};

static void subtree_work(Pool *, Task *, int *status, int *terminal);

static int task_stopped(Task *task)
{
    Pool *pool;
    int stopped;
    pool = task->pool;
    cu_mutex_lock(pool->mutex);
    stopped = pool->stop;
    cu_mutex_unlock(pool->mutex);
    return stopped;
}

/* Midstream publication, including a zero-byte explicit flush. On success
 * the producer owns the empty mailbox again. Cancellation leaves any READY
 * bytes untouched; no subsequent consumer will deliver speculative bytes. */
static int task_publish(Task *task)
{
    Pool *pool;
    int ok;
    pool = task->pool;
    cu_mutex_lock(pool->mutex);
    if (!pool->stop) {
        task->ready = 1;
        FYND_TASK_PUBLISH(task);
        cu_cond_broadcast(pool->publication);
        while (task->ready && !pool->stop)
            cu_cond_wait(pool->space, pool->mutex);
    }
    ok = !pool->stop;
    cu_mutex_unlock(pool->mutex);
    if (ok) {
        task->used = 0;
        task->flush = 0;
    } else
        task->write_stopped = 1;
    return ok;
}

static int task_write(Task *task, int channel, const char *bytes, size_t len,
                      int flush)
{
    size_t take;
    if (task->write_stopped)
        return 0;
    if (task->used != 0 && task->channel != channel && !task_publish(task))
        return 0;
    task->channel = channel;
    while (len != 0) {
        if (task->used == (size_t)FYND_TASK_BYTES && !task_publish(task))
            return 0;
        take = (size_t)FYND_TASK_BYTES - task->used;
        if (take > len)
            take = len;
        memcpy(task->bytes + task->used, bytes, take);
        task->used += take;
        bytes += take;
        len -= take;
    }
    if (flush) {
        task->flush = 1;
        return task_publish(task);
    }
    return 1;
}

static void subtree_worker(void *context)
{
    SubtreeWorker *worker;
    Pool *pool;
    Task *task;
    int status;
    int terminal;
    worker = (SubtreeWorker *)context;
    pool = worker->pool;
    cu_mutex_lock(pool->mutex);
    for (;;) {
        task = NULL;
        if (pool->stop)
            break;
        if (pool->ready)
            for (task = pool->first; task != NULL; task = task->next)
                if (task->state == TASK_QUEUED)
                    break;
        if (task == NULL) {
            cu_cond_wait(pool->work, pool->mutex);
            continue;
        }
        task->state = TASK_RUNNING;
        cu_mutex_unlock(pool->mutex);
        status = 0;
        terminal = 0;
        FYND_TASK_BEGIN(task);
        subtree_work(pool, task, &status, &terminal);
        cu_mutex_lock(pool->mutex);
        task->status = status;
        task->terminal = terminal;
        if (!pool->stop && task->used != 0) {
            task->ready = 1;
            FYND_TASK_PUBLISH(task);
        }
        task->state = TASK_DONE;
        cu_cond_broadcast(pool->publication);
    }
    cu_mutex_unlock(pool->mutex);
}

/* Coordinator-only lifecycle. Track joins separately from starts so stop at
 * any walker scope is safe, and finish also handles every partial startup. */
static void pool_abort(Pool *pool)
{
    Task *task;
    if (pool->mutex != NULL) {
        cu_mutex_lock(pool->mutex);
        pool->stop = 1;
        for (task = pool->first; task != NULL; task = task->next)
            if (task->state == TASK_QUEUED) {
                task->state = TASK_DONE;
                task->status = 1;
                task->terminal = 1;
            }
        if (pool->work != NULL)
            cu_cond_broadcast(pool->work);
        if (pool->publication != NULL)
            cu_cond_broadcast(pool->publication);
        if (pool->space != NULL)
            cu_cond_broadcast(pool->space);
        cu_mutex_unlock(pool->mutex);
    }
    while (pool->joined < pool->started) {
        cu_thread_join(pool->workers[pool->joined].thread);
        ++pool->joined;
    }
}

static void pool_finish(Pool *pool)
{
    int i;
    pool_abort(pool);
    for (i = 0; i < 32; ++i)
        cu_arena_release(&pool->slots[i]->seed);
    /* Reverse primitive acquisition order, after every successful start joins. */
    if (pool->space != NULL)
        cu_cond_destroy(pool->space);
    if (pool->publication != NULL)
        cu_cond_destroy(pool->publication);
    if (pool->work != NULL)
        cu_cond_destroy(pool->work);
    if (pool->mutex != NULL)
        cu_mutex_destroy(pool->mutex);
    cu_arena_release(&pool->arena);
}

static int pool_start(Pool *pool, int count, const Query *query)
{
    Task *task;
    int i;
    cu_arena_init(&pool->arena);
    pool->query = query;
    pool->mutex = NULL;
    pool->work = NULL;
    pool->publication = NULL;
    pool->space = NULL;
    pool->first = NULL;
    pool->last = NULL;
    pool->count = count;
    pool->pending = 0;
    pool->started = 0;
    pool->joined = 0;
    pool->ready = 0;
    pool->stop = 0;
    for (i = 0; i < 32; ++i) {
        task = &pool->tasks[i];
        pool->slots[i] = task;
        task->pool = pool;
        cu_arena_init(&task->seed);
        task->path = NULL;
        task->depth = 0;
        task->parent = NULL;
        task->next = NULL;
        task->bytes = NULL;
        task->used = 0;
        task->channel = EMIT_OUT;
        task->flush = 0;
        task->write_stopped = 0;
        task->ready = 0;
        task->state = TASK_FREE;
        task->status = 0;
        task->terminal = 0;
        pool->workers[i].pool = pool;
        pool->workers[i].thread = NULL;
    }
    if (count < 1 || count > 32 || (size_t)FYND_TASK_BYTES == 0)
        return 0;
    FYND_POOL_PREPARE(pool);
    for (i = 0; i < count; ++i) {
        pool->slots[i]->bytes = cu_arena_push_bytes(&pool->arena,
                                                   (size_t)FYND_TASK_BYTES);
        if (pool->slots[i]->bytes == NULL)
            return 0;
    }
    if (!cu_mutex_init(&pool->mutex, &pool->arena) ||
        !cu_cond_init(&pool->work, &pool->arena) ||
        !cu_cond_init(&pool->publication, &pool->arena) ||
        !cu_cond_init(&pool->space, &pool->arena))
        return 0;
    for (i = 0; i < count; ++i) {
        if (!cu_thread_start(&pool->workers[i].thread, &pool->arena, 0,
                             subtree_worker, &pool->workers[i]))
            return 0;
        ++pool->started;
    }
    cu_mutex_lock(pool->mutex);
    pool->ready = 1;
    cu_cond_broadcast(pool->work);
    cu_mutex_unlock(pool->mutex);
    return 1;
}

/* The coordinator alone allocates seeds. A failed/full offer consumes neither
 * a token nor an entry in the caller's monotonic refill cursor. */
static int pool_offer(Pool *pool, const char *directory, const WalkEntry *entry,
                      int child_depth, const IgnoreFrame *parent)
{
    Task *task;
    char *path;
    int i;
    cu_mutex_lock(pool->mutex);
    if (pool->stop || pool->pending == pool->count) {
        cu_mutex_unlock(pool->mutex);
        return 0;
    }
    task = NULL;
    for (i = 0; i < pool->count; ++i)
        if (pool->slots[i]->state == TASK_FREE) {
            task = pool->slots[i];
            break;
        }
    if (task == NULL)
        abort();
    path = join_path(&task->seed, directory, entry->name);
    if (path == NULL) {
        cu_arena_release(&task->seed);
        cu_mutex_unlock(pool->mutex);
        return -1;
    }
    task->path = path;
    task->depth = child_depth;
    task->parent = parent;
    task->next = NULL;
    task->used = 0;
    task->channel = EMIT_OUT;
    task->flush = 0;
    task->write_stopped = 0;
    task->ready = 0;
    task->status = 0;
    task->terminal = 0;
    task->state = TASK_QUEUED;
    if (pool->last == NULL)
        pool->first = task;
    else
        pool->last->next = task;
    pool->last = task;
    ++pool->pending;
    FYND_PENDING(pool);
    cu_cond_broadcast(pool->work);
    cu_mutex_unlock(pool->mutex);
    return 1;
}

/* Consume exactly the FIFO head, retaining its token throughout delivery.
 * failure() is deliberately outside mutex, with coordinator.task==NULL: its
 * diagnostics cannot recurse into or overwrite the active mailbox. */
static void pool_drain(Pool *pool, Run *coordinator)
{
    Task *task;
    const char *bytes;
    size_t len;
    int channel;
    int flush;
    int status;
    int terminal;
    cu_mutex_lock(pool->mutex);
    task = pool->first;
    if (task == NULL || pool->stop) {
        cu_mutex_unlock(pool->mutex);
        return;
    }
    for (;;) {
        while (!task->ready && task->state != TASK_DONE && !pool->stop)
            cu_cond_wait(pool->publication, pool->mutex);
        if (pool->stop) {
            cu_mutex_unlock(pool->mutex);
            return;
        }
        if (task->ready) {
            bytes = task->bytes;
            len = task->used;
            channel = task->channel;
            flush = task->flush;
            cu_mutex_unlock(pool->mutex);
            if (!emit(coordinator, channel, bytes, len, flush)) {
                if (channel == EMIT_OUT)
                    failure(coordinator, "output failure", NULL, 1);
                else {
                    coordinator->status = 1;
                    coordinator->stop = 1;
                }
                pool_abort(pool);
                return;
            }
            cu_mutex_lock(pool->mutex);
            task->ready = 0;
            cu_cond_broadcast(pool->space);
        }
        if (task->state == TASK_DONE)
            break;
    }
    status = task->status;
    terminal = task->terminal;
    pool->first = task->next;
    if (pool->first == NULL)
        pool->last = NULL;
    task->next = NULL;
    task->path = NULL;
    task->parent = NULL;
    task->state = TASK_FREE;
    --pool->pending;
    FYND_PENDING(pool);
    cu_mutex_unlock(pool->mutex);
    cu_arena_release(&task->seed);
    if (status != 0)
        coordinator->status = 1;
    if (terminal) {
        coordinator->status = 1;
        coordinator->stop = 1;
        pool_abort(pool);
    }
}

